import React, { Component } from 'react'

export class NewsItem extends Component {
  // constructor(){
  //   super();
  //   console.log("hello ,i am a constructor")
  // }
  render() {
    let {title,description,imageurl,newsUrl,author,date} = this.props;
    return (
      < div className="my-3">
       <div class="card" style={{width: "18rem"}}>
  <img src={!imageurl?"https://deadline.com/wp-content/uploads/2024/08/MCDDEAN_WD032-e1723021393743.jpg?w=1024":imageurl} class="card-img-top" alt="..."/>
  <div class="card-body">
    <h5 class="card-title">{title}</h5>
    <p class="card-text">{description}</p>
    <p class="card-text"><small class="text-body-secondary"> By {!author?Unknown:author} on {date}</small></p>
    <a rel="noreferrer" href={newsUrl} target="_blank" class="btn btn-primary">Read More</a>
  </div>
       </div>
  </div>
    )
  }
}

export default NewsItem
